524	// duplicateResultSeqError 表示待保存记录中有两份不同修读的已提交成绩共用同一个
525	// 正整数结果提交顺序编号。seq 是冲突的编号；first/second 各用完整学生编号与
526	// 修读编号共同指明冲突双方，便于调用方分辨不同学生名下编号相同的修读（例如
527	// 两名学生各有一份 e1）。顺序按修读在记录中的先后确定，first 先出现。
528	type duplicateResultSeqError struct {
529		seq           int
530		firstStudent  string
531		firstEnr      string
532		secondStudent string
533		secondEnr     string
534	}
535	
536	func (e *duplicateResultSeqError) Error() string {
537		return fmt.Sprintf(
538			"成绩提交顺序编号 %d 被两份不同修读的已提交成绩共用：学生 %s 的修读 %s 与学生 %s 的修读 %s",
539			e.seq, e.firstStudent, e.firstEnr, e.secondStudent, e.secondEnr)
540	}
541	
542	// validateResultSeqUniqueness 检查全部已提交成绩的结果提交顺序编号互不相同。
543	//
544	// 顺序编号刻画的是整份记录中每次“首次提交成绩”的先后，通过与未通过都占用
545	// 一次编号，它不按学生、课程要求或学期各自编号：同一学生的重复修读、不同
546	// 要求下的独立提交、不同学生的独立修读，只要两份不同修读的已提交成绩共用
547	// 同一个正整数编号，写出的文件随后就会被 Load 判为内容损坏。因此这样的
548	// 待保存记录必须在序列化与临时文件之前整次拒绝保存——绝不删修读、不替
549	// 调用方重新编号、不清成绩或免修历史，也不能用这份记录替换掉原本可用的
550	// 记录文件。
551	//
552	// 尚未提交结果、仍处于选课状态的修读沿用编号 0，多份并存不构成重复，本
553	// 检查直接跳过它们；判定只看已提交成绩携带的正整数编号，因此已提交编号有
554	// 空缺（不连续）合法，冲突记录之间夹着其他正常成绩或免修也不能掩盖冲突。
555	// 以修读在记录中的先后取最先相撞的一对，结果确定且与 map 遍历顺序无关。
556	func (s *Store) validateResultSeqUniqueness() error {
557		first := map[int]*Enrollment{}
558		for _, e := range s.enrollments {
559			if e == nil || e.Result == Enrolled {
560				// 选课记录的编号一律是 0，多份并存正常，不参与重复判定。
561				continue
562			}
563			if e.ResultSeq <= 0 {
564				// 本规则只管“正整数顺序编号被共用”：非正编号不是这里的判定对象。
565				continue
566			}
567			if prev := first[e.ResultSeq]; prev != nil {
568				return &duplicateResultSeqError{
569					seq:           e.ResultSeq,
570					firstStudent:  prev.StudentID,
571					firstEnr:     prev.ID,
572					secondStudent: e.StudentID,
573					secondEnr:     e.ID,
574				}
575			}
576			first[e.ResultSeq] = e
577		}
578		return nil
579	}
580	
581	// duplicateApprovedWaiverError 表示待保存记录中同一学生名下的同一项课程要求
582	// 同时有两份不同编号、状态为有效（approved）的免修。student 是所属学生编号，
583	// req 是要求编号，first/second 是冲突的两份免修编号（按免修在记录中的先后，
584	// first 先出现），便于调用方定位具体申请。
585	type duplicateApprovedWaiverError struct {
586		student string
587		req     string
588		first   string
589		second  string
590	}
591	
592	func (e *duplicateApprovedWaiverError) Error() string {
593		return fmt.Sprintf(
594			"学生 %s 的要求 %s 同时存在两份有效免修 %s 与 %s，同一要求只能由一份有效免修取代",
595			e.student, e.req, e.first, e.second)
596	}
597	
598	// validateApprovedWaiverUniqueness 检查同一学生名下的同一项要求至多有一份有效
599	// 免修。正常申请流程会拒绝为已有有效免修的要求再生效第二份，读取记录文件时
600	// （loadData）也拒绝这类冲突；但调用方取得免修记录后可以直接修改其内容——把
601	// 另一份申请改成有效，或把一份有效申请的目标改到已由免修满足的要求——这样
602	// 写出的文件随后必然被 Load 判为内容损坏。因此这样的待保存记录必须在序列化
603	// 与临时文件之前整次拒绝保存：绝不删除申请、不替调用方选定一份有效免修，也
604	// 不改状态、目标要求或依据，更不能用这份记录替换掉原本可用的记录文件。
605	//
606	// 冲突只按（所属学生、目标要求）的完整编号判定，沿用 ownerKey 的既有匹配规则：
607	// 编号前后的空白也是编号内容，“ r1 ”与“r1 ”是两项不同要求，各自的有效免修
608	// 互不冲突。两份申请依据相同也不是同一份免修，仍按编号区分；该要求另有通过
609	// 修读、已经能获得学分，或冲突申请之间夹着其他合法历史，都不能掩盖冲突。
610	// 已拒绝、已撤销的申请不占用有效名额，与一份有效免修共存时照常保存。
611	// 以免修在记录中的先后取最先相撞的一对，结果确定且与 map 遍历顺序无关。
612	func (s *Store) validateApprovedWaiverUniqueness() error {
613		approved := map[ownerKey]string{} // (student, req) -> waiverID
614		for _, w := range s.waivers {
615			if w == nil || w.Status != WaiverApproved {
616				// 失效申请（已拒绝/已撤销）不满足任何要求，不参与有效名额判定。
617				continue
618			}
619			rk := reqKey(w.StudentID, w.ReqID)
620			if other, dup := approved[rk]; dup {
621				return &duplicateApprovedWaiverError{
622					student: w.StudentID,
623					req:     w.ReqID,
624					first:   other,
625					second:  w.ID,
626				}
627			}
628			approved[rk] = w.ID
629		}
630		return nil
631	}
