633	// checkSaveText 校验单个待保存字段的文字是否为合法 UTF-8。
634	func checkSaveText(category, id, field, value string) error {
635		if !utf8.ValidString(value) {
636			return &invalidTextError{category: category, id: id, field: field}
637		}
638		return nil
639	}
