641	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
642	// 避免写到一半时损坏原文件。
643	//
644	// 写入前先做三项检查：
645	//
646	// 一是全部待保存字符串都必须是合法 UTF-8：标准库序列化会把非法字节静默
647	// 替换成 U+FFFD，因此含非法文字的数据绝不能进入序列化与临时文件阶段。
648	// 校验失败时整次保存直接返回错误——不创建/不改动目标文件（目标原本不
649	// 存在时也不会留下新记录文件或临时文件），不替换、清空或修补待保存记录
650	// 中的任何原始字符串，即使问题只出现在一条已拒绝或已撤销免修的字段里。
651	//
652	// 二是全部已提交成绩的结果提交顺序编号互不相同：顺序编号表示整份记录中
653	// 每次首次提交成绩的先后，通过与未通过都占用一次编号，不按学生、要求或
654	// 学期各自编号。两份不同修读（同一学生的重复修读或不同学生的独立修读，
655	// 无论修读编号、要求编号、学期是否相同，也无论两条记录是否相邻）的已提交
656	// 成绩共用同一个正整数编号时，写出的文件随后必然被 Load 判为内容损坏，
657	// 因此直接拒绝整次保存：错误点名目标文件、重复编号及冲突双方（完整学生
658	// 编号 + 修读编号），已有文件全部内容原样保留，目标原本不存在时不创建
659	// 记录文件也不遗留临时文件；待保存的内存记录同样原样保留——不删修读、
660	// 不替调用方调整顺序、不清成绩或免修历史。仍是选课、尚未提交结果的修读
661	// 沿用编号 0，多份并存不构成重复；已提交编号有空缺（不连续）仍合法。
662	//
663	// 三是同一学生名下的同一项要求至多有一份有效免修：正常申请流程与 Load 都
664	// 拒绝同一要求同时存在两份有效免修，但调用方取得免修记录后可以直接改内容
665	// （把另一份申请改成有效，或把有效申请的目标改到已由免修满足的要求），
666	// 这样写出的文件随后必然被 Load 判为内容损坏。因此直接拒绝整次保存：错误
667	// 点名目标文件、所属学生、要求编号与冲突的两份免修编号，已有文件全部内容
668	// 原样保留，目标原本不存在时不创建记录文件也不遗留临时文件；待保存的内存
669	// 记录同样原样保留——不删除申请、不替调用方选定一份有效免修，也不改状态、
670	// 目标要求或依据。冲突只按（所属学生、目标要求）的完整编号判定，编号前后
671	// 的空白也是编号内容；两份申请依据相同仍算两份；该要求另有通过修读、冲突
672	// 申请之间夹着其他合法历史都不能掩盖冲突。不同学生各自拥有同号要求、同号
673	// 免修是合法的；同一学生的不同要求各有一份有效免修也正常保存；已拒绝、
674	// 已撤销的历史不占用有效名额，与一份有效免修共存时照常保存。
675	func (s *Store) Save(path string) (err error) {
676		if err := s.validateSaveText(); err != nil {
677			return fmt.Errorf("记录中存在无法原样保存的文字，拒绝写入 %s：%w", path, err)
678		}
679		if err := s.validateResultSeqUniqueness(); err != nil {
680			return fmt.Errorf("记录中的成绩提交顺序编号冲突，拒绝写入 %s，已有文件保持原样：%w", path, err)
681		}
682		if err := s.validateApprovedWaiverUniqueness(); err != nil {
683			return fmt.Errorf("记录中存在有效免修冲突，拒绝写入 %s，已有文件保持原样：%w", path, err)
684		}
685		data := fileData{
686			Version:       recordVersion,
687			Courses:       s.courses,
688			Students:      s.students,
689			Requirements:  s.requirements,
690			Enrollments:   s.enrollments,
691			Waivers:       s.waivers,
692			NextResultSeq: s.nextResultSeq,
693		}
694		buf, err := json.MarshalIndent(&data, "", "  ")
695		if err != nil {
696			return fmt.Errorf("无法序列化记录：%w", err)
697		}
698		buf = append(buf, '\n')
699	
700		dir := filepath.Dir(path)
701		if dir == "" {
702			dir = "."
703		}
704		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
705		if err != nil {
706			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
707		}
708		tmpName := tmp.Name()
709		defer func() {
710			if err != nil {
711				tmp.Close()
712				os.Remove(tmpName)
713			}
714		}()
715		if _, err = tmp.Write(buf); err != nil {
716			return fmt.Errorf("写入记录文件失败：%w", err)
717		}
718		if err = tmp.Sync(); err != nil {
719			return fmt.Errorf("写入记录文件失败：%w", err)
720		}
721		if err = tmp.Close(); err != nil {
722			return fmt.Errorf("写入记录文件失败：%w", err)
723		}
724		if err = os.Chmod(tmpName, 0o600); err != nil {
725			return fmt.Errorf("设置记录文件权限失败：%w", err)
726		}
727		if err = os.Rename(tmpName, path); err != nil {
728			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
729		}
730		return nil
731	}
