			// 业务拒绝（例如历史都没存上的被拒绝免修）。
			fmt.Fprintf(stderr, "错误：保存记录文件 %s 失败：%v\n", *file, saveErr)
			return exitFile
		}
		// 首次创建记录文件的说明放在业务结果之后；保存失败时不会出现，
		// 也不会谎称已经创建。
		fmt.Fprint(stdout, biz.String())
		if !existed {
			fmt.Fprintf(stdout, "（记录文件 %s 不存在，已从空记录开始并创建）\n", *file)
		}
		return code
	}
	fmt.Fprint(stdout, biz.String())
	return code
}

